};
const parseUntil = (rule, master) => {
  if (!rule?.UNTIL) return null;
  const parsed = parseDateProp({ name:'UNTIL', params:{}, value:rule.UNTIL }, master.start.timezone || master.calendarTz);
  if (!parsed) return null;
  return parsed.allDay ? parsed.ms + 86400000 - 1 : parsed.ms;
};

const expandMaster = (master, rangeStart, rangeEnd, warnings) => {
  const rule = parseRrule(master.rrule);
  const out = [];
  const seen = new Set();
  const ex = new Set(master.exdates.map(String));
  const add = (ms, recurrenceBaseMs = ms) => {
    if (!Number.isFinite(ms) || seen.has(ms)) return;
    seen.add(ms);
    out.push({ startMs: ms, recurrenceBaseMs });
  };
  if (!rule) { add(master.start.ms); for (const ms of master.rdates) add(ms); return out; }

  const tz = master.start.timezone || master.calendarTz || targetTimezone;
  const startLocal = partsAt(master.start.ms, tz);
  const untilMs = parseUntil(rule, master);
  const maxCount = Number.isFinite(rule.COUNT) ? rule.COUNT : Infinity;
  let emittedCount = 0;
  let iterations = 0;
  const maxIterations = 50000;
  const byMonth = new Set(String(rule.BYMONTH || '').split(',').filter(Boolean).map(Number));
  const byMonthDay = String(rule.BYMONTHDAY || '').split(',').filter(Boolean).map(Number);
  const byDay = parseByDay(rule.BYDAY);
  const acceptCommon = (local) => {
    if (byMonth.size && !byMonth.has(local.month)) return false;
    if (byMonthDay.length) {
      const dim = daysInMonth(local.year, local.month);
      const vals = byMonthDay.map((n) => n > 0 ? n : dim + n + 1);
      if (!vals.includes(local.day)) return false;
    }
    if (byDay.length && !byDay.some((d) => d.weekday === weekday(local))) return false;
    return true;
  };
  const emitCandidate = (local) => {
    if (iterations++ > maxIterations) throw new Error(`Recurrence expansion exceeded ${maxIterations} candidates for UID ${master.uid}`);
    if (!acceptCommon(local)) return false;
    const ms = zonedToUtc(local, tz);
    if (ms < master.start.ms) return false;
    if (untilMs !== null && ms > untilMs) return 'stop';
    emittedCount++;
    if (emittedCount > maxCount) return 'stop';
    if (!ex.has(String(ms))) add(ms);
    return false;
  };

  const stopAfterRange = (ms) => ms > rangeEnd + 2 * 86400000 && emittedCount >= maxCount;

  if (rule.FREQ === 'DAILY') {
    for (let n = 0; ; n++) {
      const base = localDateMath(startLocal, n * rule.INTERVAL);
      const local = { ...base, hour:startLocal.hour, minute:startLocal.minute, second:startLocal.second };
      const approxMs = zonedToUtc(local, tz);
      if (untilMs !== null && approxMs > untilMs) break;
      if (approxMs > rangeEnd + 86400000 && emittedCount >= Math.min(maxCount, 1)) break;
      const stop = emitCandidate(local); if (stop === 'stop') break;
    }
  } else if (rule.FREQ === 'WEEKLY') {
    const wkst = dayCodes[String(rule.WKST || 'MO').toUpperCase()] ?? 1;
    const startWd = weekday(startLocal);
    const deltaToWeekStart = (startWd - wkst + 7) % 7;
    const week0 = localDateMath(startLocal, -deltaToWeekStart);
    const specs = byDay.length ? byDay : [{ weekday:startWd, ordinal:null }];
    const sortedSpecs = [...specs].sort((a,b) => ((a.weekday-wkst+7)%7)-((b.weekday-wkst+7)%7));
    outer: for (let w=0;;w++) {
      const weekStart = localDateMath(week0, w * rule.INTERVAL * 7);
      for (const spec of sortedSpecs) {
        const localDate = localDateMath(weekStart, (spec.weekday - wkst + 7) % 7);
        const local = { ...localDate, hour:startLocal.hour, minute:startLocal.minute, second:startLocal.second };
        const ms = zonedToUtc(local, tz);
        if (untilMs !== null && ms > untilMs) break outer;
        if (ms > rangeEnd + 8*86400000 && emittedCount >= Math.min(maxCount,1)) break outer;
        const stop = emitCandidate(local); if (stop === 'stop') break outer;
      }
    }
  } else if (rule.FREQ === 'MONTHLY') {
    const startIndex = startLocal.year * 12 + (startLocal.month - 1);
    outer: for (let n=0;;n++) {
      const idx = startIndex + n * rule.INTERVAL;
      const year = Math.floor(idx / 12), month = (idx % 12) + 1;
      if (byMonth.size && !byMonth.has(month)) continue;
      const days = monthCandidateDays(year, month, startLocal.day, rule);
      for (const day of days) {
        const local = { year, month, day, hour:startLocal.hour, minute:startLocal.minute, second:startLocal.second };
        const ms = zonedToUtc(local, tz);
        if (untilMs !== null && ms > untilMs) break outer;
        if (ms > rangeEnd + 35*86400000 && emittedCount >= Math.min(maxCount,1)) break outer;
        const stop = emitCandidate(local); if (stop === 'stop') break outer;
      }
    }
  } else if (rule.FREQ === 'YEARLY') {
    outer: for (let n=0;;n++) {
      const year = startLocal.year + n * rule.INTERVAL;
      const months = byMonth.size ? [...byMonth].sort((a,b)=>a-b) : [startLocal.month];
      for (const month of months) {
        const days = monthCandidateDays(year, month, startLocal.day, rule);
        for (const day of days) {
          const local = { year, month, day, hour:startLocal.hour, minute:startLocal.minute, second:startLocal.second };
          const ms = zonedToUtc(local, tz);
          if (untilMs !== null && ms > untilMs) break outer;
          if (ms > rangeEnd + 370*86400000 && emittedCount >= Math.min(maxCount,1)) break outer;
          const stop = emitCandidate(local); if (stop === 'stop') break outer;
        }
      }
    }
  } else if (rule.FREQ === 'HOURLY' || rule.FREQ === 'MINUTELY') {
    const step = rule.INTERVAL * (rule.FREQ === 'HOURLY' ? 3600000 : 60000);
    for (let ms = master.start.ms; ; ms += step) {
      if (iterations++ > maxIterations) throw new Error(`Recurrence expansion exceeded ${maxIterations} candidates for UID ${master.uid}`);
      if (untilMs !== null && ms > untilMs) break;
      emittedCount++;
      if (emittedCount > maxCount) break;
      if (!ex.has(String(ms))) add(ms);
      if (ms > rangeEnd + step) break;
    }
  } else {
    warnings.push(`UID ${master.uid}: unsupported RRULE FREQ=${rule.FREQ}; only DTSTART/RDATE were considered.`);
    add(master.start.ms);
  }

  for (const ms of master.rdates) if (!ex.has(String(ms))) add(ms);
  return out;
};

const eventJoinLink = (event) => {
  const haystack = [event.url, event.location, event.description, ...(event.meetingValues || [])].filter(Boolean).join('\n');
  const urls = haystack.match(/https?:\/\/[^\s<>"']+/gi) || [];
  const cleaned = urls.map((u) => decodeXml(u).replace(/[),.;]+$/g, ''));
  const google = cleaned.find((u) => /https?:\/\/(?:meet\.google\.com|g\.co\/meet)\//i.test(u));
  if (google) return { url:google, type:'google_meet' };
  const teams = cleaned.find((u) => /https?:\/\/(?:teams\.microsoft\.com\/(?:l\/meetup-join|meet)|teams\.live\.com\/meet)\//i.test(u));
  if (teams) return { url:teams, type:'microsoft_teams' };
  return { url:null, type:null };
};

const chooseNewest = (items) => [...items].sort((a,b) => (b.sequence-a.sequence) || String(b.lastModified||'').localeCompare(String(a.lastModified||'')))[0];
const materializeOccurrences = (parsedEvents, calendar, warnings) => {
  const groups = new Map();
  for (const event of parsedEvents) {
    if (!groups.has(event.uid)) groups.set(event.uid, []);
    groups.get(event.uid).push(event);
  }
  const occurrences = [];
  for (const [uid, items] of groups) {
    const masters = items.filter((e) => !e.recurrenceId);
    const overrides = items.filter((e) => e.recurrenceId);
    const overrideMap = new Map();
    for (const o of overrides) {
      const key = String(o.recurrenceId.ms);
      const existing = overrideMap.get(key);
      if (!existing || chooseNewest([o, existing]) === o) overrideMap.set(key, o);
    }
    const usedOverrides = new Set();
    if (masters.length) {
      const master = chooseNewest(masters);
      const generated = expandMaster(master, dayStartMs, horizonEndMs, warnings);
      for (const generatedOccurrence of generated) {
        const originalMs = generatedOccurrence.recurrenceBaseMs;
        const override = overrideMap.get(String(originalMs));
        let source = master;
        let startMs = generatedOccurrence.startMs;
        let recurrenceIdentityMs = originalMs;
        if (override) {
          usedOverrides.add(String(originalMs));
          if (override.status === 'CANCELLED') continue;
          source = override;
          startMs = override.start.ms;
        }
        if (source.status === 'CANCELLED') continue;
        if (startMs < dayStartMs || startMs >= horizonEndMs) continue;
        const join = eventJoinLink(source);
        occurrences.push({ source, startMs, endMs:startMs + Math.max(0, Number(source.durationMs || master.durationMs || 0)), recurrenceIdentityMs, join });
      }
    }
    for (const override of overrides) {
      const key = String(override.recurrenceId.ms);
      if (usedOverrides.has(key) || override.status === 'CANCELLED') continue;
      const startMs = override.start.ms;
      if (startMs < dayStartMs || startMs >= horizonEndMs) continue;
      const join = eventJoinLink(override);
      occurrences.push({ source:override, startMs, endMs:startMs + Math.max(0, Number(override.durationMs || 0)), recurrenceIdentityMs:override.recurrenceId.ms, join });
    }
  }

  const dedupe = new Map();
  for (const o of occurrences) {
    const key = `${o.source.uid}|${o.recurrenceIdentityMs}|${o.startMs}`;
    const existing = dedupe.get(key);
    if (!existing || chooseNewest([o.source, existing.source]) === o.source) dedupe.set(key, o);
  }
  return [...dedupe.values()].sort((a,b)=>a.startMs-b.startMs);
};

const fetchCalendarIcs = async (calendar) => {
  if (calendar.kind === 'nextcloud_caldav') {
    if (!calendar.caldavUrl) throw new Error('Missing caldavUrl');
    const rangeStart = new Date(dayStartMs).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/, 'Z');
    const rangeEnd = new Date(horizonEndMs).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/, 'Z');
    const reportBody = `<?xml version="1.0" encoding="UTF-8"?>\n<c:calendar-query xmlns:d="DAV:" xmlns:c="urn:ietf:params:xml:ns:caldav">\n  <d:prop><d:getetag/><c:calendar-data/></d:prop>\n  <c:filter><c:comp-filter name="VCALENDAR"><c:comp-filter name="VEVENT"><c:time-range start="${rangeStart}" end="${rangeEnd}"/></c:comp-filter></c:comp-filter></c:filter>\n</c:calendar-query>`;
    const res = await this.helpers.httpRequest({
      method:'REPORT', url:calendar.caldavUrl,
      auth:{ username:cfg.nextcloud.user, password:cfg.nextcloud.password },
      headers:{ Depth:'1', Accept:'application/xml, text/xml;q=0.9, */*;q=0.1', 'Content-Type':'application/xml; charset=UTF-8' },
      body:reportBody, encoding:'text', timeout:30000, returnFullResponse:true, ignoreHttpStatusErrors:true,
    });
    const status = Number(res?.statusCode || 0);
    const xml = bodyToText(res?.body);
    if (status < 200 || status >= 300) throw new Error(`CalDAV REPORT returned HTTP ${status || 'unknown'}: ${compact(xml) || '(empty body)'}`);
    const blocks = [...xml.matchAll(/<(?:\w+:)?calendar-data\b[^>]*>([\s\S]*?)<\/(?:\w+:)?calendar-data>/gi)].map((m)=>decodeXml(m[1]));
    return blocks.join('\r\n');
  }

  if (calendar.kind === 'subscription_ics') {
    if (!calendar.icsUrl) throw new Error('Missing icsUrl');
    const res = await this.helpers.httpRequest({
      method:'GET', url:calendar.icsUrl,
      headers:{ Accept:'text/calendar, text/plain;q=0.9, */*;q=0.1' },
      encoding:'text', timeout:30000, returnFullResponse:true, ignoreHttpStatusErrors:true,
    });
    const status = Number(res?.statusCode || 0);
    const body = bodyToText(res?.body);
    if (status < 200 || status >= 300) throw new Error(`ICS fetch returned HTTP ${status || 'unknown'}: ${compact(body) || '(empty body)'}`);
    if (!/BEGIN:VCALENDAR/i.test(body)) throw new Error(`ICS response is not a VCALENDAR document: ${compact(body)}`);
    return body;
  }
  throw new Error(`Unsupported calendar kind: ${calendar.kind}`);
};

const normalizedEventForOccurrence = (occ, calendar, calendarId) => {
  const source = occ.source;
  const recurrenceToken = source.recurrenceId?.ms ?? occ.recurrenceIdentityMs ?? occ.startMs;
  const recurring = Boolean(source.recurrenceId || source.rrule || (source.rdates && source.rdates.length) || (source.exdates && source.exdates.length));
  const changeIdentity = recurring ? `${source.uid}|r:${recurrenceToken}` : `${source.uid}|single`;
  const occurrenceHash = fnv1a(`${source.uid}|${recurrenceToken}`);
  const eventKey = `calendar-notifier:event:v1:${calendarId}:${occurrenceHash}`;
  return {
    schemaVersion:1,
    eventKey,
    changeIdentity,
    calendarId,
    calendarName:calendar.displayName,
    calendarKind:calendar.kind,
    uid:source.uid,
    recurrenceIdUtc:new Date(recurrenceToken).toISOString(),
    title:source.summary,
    description:source.description,
    location:source.location,
    status:source.status,
    sequence:source.sequence,
    startUtc:new Date(occ.startMs).toISOString(),
    endUtc:new Date(occ.endMs).toISOString(),
    startLocal:formatLocal(occ.startMs, targetTimezone),
    endLocal:formatLocal(occ.endMs, targetTimezone),
    timezone:targetTimezone,
    originalTimezone:source.start.timezone || source.calendarTz || null,
    allDay:Boolean(source.start.allDay),
    meetingUrl:occ.join.url,
    meetingType:occ.join.type,
    sourceUrl:calendar.icsUrl,
  };
};

const comparisonSnapshot = (event) => ({
  identity:event.changeIdentity,
  uid:event.uid,
  recurrenceIdUtc:event.recurrenceIdUtc,
  eventKey:event.eventKey,
  title:event.title || '',
  startUtc:event.startUtc,
  endUtc:event.endUtc,
  location:event.location || '',
  meetingUrl:event.meetingUrl || null,
  meetingType:event.meetingType || null,
  allDay:Boolean(event.allDay),
});

const changeFieldMap = {
  title:'title', startUtc:'start_time', endUtc:'end_time', location:'location',
  meetingUrl:'meeting_link', meetingType:'meeting_type', allDay:'all_day',
};
const diffSnapshots = (before, after) => Object.keys(changeFieldMap)
  .filter((field) => stableStringify(before?.[field] ?? null) !== stableStringify(after?.[field] ?? null))
  .map((field) => changeFieldMap[field]);
const transitionRelevantNow = (before, after) => {
  const beforeMs = Date.parse(before?.startUtc || '');
  const afterMs = Date.parse(after?.startUtc || '');
  return (Number.isFinite(beforeMs) && beforeMs > nowMs - graceMs) || (Number.isFinite(afterMs) && afterMs > nowMs - graceMs);
};
const dualHash = (value) => `${fnv1a(value)}${fnv1a(`calendar-change:${value}`)}`;
const buildChangeMessageWrite = (messageType, reason, calendar, calendarId, before, after, changedFields = []) => {
  const core = {
    schemaVersion:1,
    messageType,
    reason,
    createdAt:cfg.scan.nowIso,
    calendarId,
    calendarName:calendar.displayName,
    calendarKind:calendar.kind,
    eventIdentityBefore:before?.identity || null,
    eventIdentityAfter:after?.identity || null,
    uid:after?.uid || before?.uid || null,
    title:after?.title || before?.title || '(untitled event)',
    startUtc:after?.startUtc || before?.startUtc || null,
    startLocal:(after?.startUtc || before?.startUtc) ? formatLocal(Date.parse(after?.startUtc || before?.startUtc), targetTimezone) : null,
    meetingUrl:after?.meetingUrl || before?.meetingUrl || null,
    meetingType:after?.meetingType || before?.meetingType || null,
    changedFields,
    before:before || null,
    after:after || null,
  };
  const fingerprintPayload = stableStringify({
    messageType, reason, calendarId,
    before:before || null, after:after || null, changedFields,
  });
  const messageId = dualHash(fingerprintPayload);
  const key = `calendar-notifier:message:v1:${calendarId}:${messageId}`;
  const payload = { ...core, messageId, redisKey:key };
  return { key, value:JSON.stringify(payload), ttlSeconds:changeMessageTtlSeconds, category:'change_message', messageType };
};

const previousCalendars = previousState?.calendars && typeof previousState.calendars === 'object' ? previousState.calendars : {};
const nextCalendarStates = {};
const currentKeyValues = new Map();
const deleteKeys = new Set();
const changeMessageWrites = [];
const scanErrors = [];
const scanWarnings = [];
const sourceCalendarIds = new Set();
const calendarRefs = [];
let totalEvents = 0;
let totalReminders = 0;
let changedMessageCount = 0;
let deletedMessageCount = 0;

for (const calendar of sourceCache.calendars) {
  if (calendar.supportsVEvent === false) continue;
  const identity = `${calendar.kind}|${calendar.caldavUrl || ''}|${calendar.icsUrl || ''}`;
  const calendarId = fnv1a(identity);
  sourceCalendarIds.add(calendarId);
  calendarRefs.push({ calendarId, displayName:calendar.displayName, kind:calendar.kind });
  const previousCalendar = previousCalendars[calendarId] || null;
  try {
    const ics = await fetchCalendarIcs(calendar);
    const parsed = parseCalendar(ics, calendar);
    const cancelledExactIdentities = new Set();
    const cancelledMasterUids = new Set();
    for (const rawEvent of parsed) {
      if (rawEvent.status !== 'CANCELLED') continue;
      if (rawEvent.recurrenceId?.ms !== undefined && rawEvent.recurrenceId?.ms !== null) {
        cancelledExactIdentities.add(`${rawEvent.uid}|r:${rawEvent.recurrenceId.ms}`);
      } else {
        cancelledMasterUids.add(rawEvent.uid);
      }
    }
    const warnings = [];
    // Materialize the bounded two-local-day horizon (today + tomorrow) for comparison.
    // Only future-starting occurrences below are written into reminder/event scheduling keys.
    const occurrences = materializeOccurrences(parsed, calendar, warnings);
    for (const warning of warnings) scanWarnings.push(`${calendar.displayName}: ${warning}`);

    const normalized = occurrences.map((occ) => ({ occ, event:normalizedEventForOccurrence(occ, calendar, calendarId) }));
    const currentSnapshots = {};
    for (const { event } of normalized) currentSnapshots[event.changeIdentity] = comparisonSnapshot(event);

    // Change/deletion detection is enabled only after this calendar has a snapshot
    // baseline. This avoids emitting a burst of false "created/changed" messages
    // the first time v2 runs against a v1 scan-state record.
    const previousSnapshots = previousCalendar?.eventSnapshots && typeof previousCalendar.eventSnapshots === 'object'
      ? previousCalendar.eventSnapshots : null;
    if (previousSnapshots) {
      const unmatchedPrevious = new Set(Object.keys(previousSnapshots));
      const unmatchedCurrent = new Set(Object.keys(currentSnapshots));

      const emitChanged = (before, after) => {
        const changedFields = diffSnapshots(before, after);
        if (!changedFields.length || !transitionRelevantNow(before, after)) return;
        changeMessageWrites.push(buildChangeMessageWrite('event_changed', 'event_fields_changed', calendar, calendarId, before, after, changedFields));
        changedMessageCount++;
      };

      // Exact occurrence identities first.
      for (const id of [...unmatchedPrevious]) {
        if (!unmatchedCurrent.has(id)) continue;
        emitChanged(previousSnapshots[id], currentSnapshots[id]);
        unmatchedPrevious.delete(id);
        unmatchedCurrent.delete(id);
      }

      // If a provider changes the recurrence/start identity itself, pair an
      // otherwise-unmatched previous/current occurrence when that UID is
      // unambiguous for this local day. This turns common reschedules into a
      // change notification instead of a deletion.
      const previousByUid = new Map();
      const currentByUid = new Map();
      for (const id of unmatchedPrevious) {
        const uid = previousSnapshots[id]?.uid || '';
        if (!previousByUid.has(uid)) previousByUid.set(uid, []);
        previousByUid.get(uid).push(id);
      }
      for (const id of unmatchedCurrent) {
        const uid = currentSnapshots[id]?.uid || '';
        if (!currentByUid.has(uid)) currentByUid.set(uid, []);
        currentByUid.get(uid).push(id);
      }
      for (const [uid, prevIds] of previousByUid) {
        const currIds = currentByUid.get(uid) || [];
        if (!uid || prevIds.length !== 1 || currIds.length !== 1) continue;
        const prevId = prevIds[0], currId = currIds[0];
        emitChanged(previousSnapshots[prevId], currentSnapshots[currId]);
        unmatchedPrevious.delete(prevId);
        unmatchedCurrent.delete(currId);
      }

      // A missing occurrence is considered deleted/cancelled only after a
      // successful authoritative fetch and only if it had not naturally aged
      // out of the upcoming window. Fetch failures never enter this branch.
      for (const id of unmatchedPrevious) {
        const before = previousSnapshots[id];
        const previousStartMs = Date.parse(before?.startUtc || '');
        if (!Number.isFinite(previousStartMs) || previousStartMs <= nowMs - graceMs) continue;
        const deleteReason = cancelledExactIdentities.has(id) || cancelledMasterUids.has(before?.uid)
          ? 'cancelled' : 'missing_after_successful_scan';
        changeMessageWrites.push(buildChangeMessageWrite('event_deleted', deleteReason, calendar, calendarId, before, null, []));
        deletedMessageCount++;
      }
    }

    const owned = {};
    const eventSummaries = [];
    const buckets = new Map();
    for (const { occ, event } of normalized) {
      if (occ.startMs <= nowMs) continue;
      const eventValue = JSON.stringify(event);
      const eventHash = fnv1a(eventValue);
      currentKeyValues.set(event.eventKey, { value:eventValue, hash:eventHash, ttlSeconds, category:'event', calendarId });
      owned[event.eventKey] = eventHash;
      eventSummaries.push(event);
      totalEvents++;

      for (const offset of offsets) {
        const triggerMs = occ.startMs - offset * 60000;
        if (triggerMs < nowMs - graceMs) continue;
        const minuteMs = Math.ceil(triggerMs / 60000) * 60000;
        const minuteStamp = new Date(minuteMs).toISOString().replace(/[-:]/g,'').replace(/\.000Z$/,'Z');
        const bucketKey = `calendar-notifier:reminders:v1:${offset}:${minuteStamp}:${calendarId}`;
