          eventKey:event.eventKey,
          eventRevision:eventHash,
          offsetMinutes:offset,
          scheduledForUtc:new Date(triggerMs).toISOString(),
          scheduledMinuteUtc:new Date(minuteMs).toISOString(),
          startUtc:event.startUtc,
          startLocal:event.startLocal,
          title:event.title,
          calendarName:event.calendarName,
          allDay:event.allDay,
          meetingUrl:event.meetingUrl,
          meetingType:event.meetingType,
        });
        totalReminders++;
      }
    }

    for (const [bucketKey, entries] of buckets) {
      entries.sort((a,b)=>a.startUtc.localeCompare(b.startUtc) || a.eventKey.localeCompare(b.eventKey));
      const value = JSON.stringify({ schemaVersion:1, calendarId, entries });
      const hash = fnv1a(value);
      currentKeyValues.set(bucketKey, { value, hash, ttlSeconds, category:'reminder_bucket', calendarId });
      owned[bucketKey] = hash;
    }

    // Keep one Redis day snapshot per calendar for today and tomorrow. The sender
    // consumes tomorrow's snapshots at 21:00 local time for the nightly digest.
    for (const snapshotDate of [cfg.scan.localDate, tomorrowDate]) {
      const dayEvents = eventSummaries.filter((event) => dateKeyInZone(Date.parse(event.startUtc), targetTimezone) === snapshotDate);
      const snapshotKey = `calendar-notifier:events:day:v1:${snapshotDate}:${calendarId}`;
      const snapshotValue = JSON.stringify({
        schemaVersion:1,
        date:snapshotDate,
        timezone:targetTimezone,
        calendarId,
        calendarName:calendar.displayName,
        calendarKind:calendar.kind,
        events:dayEvents,
      });
      const snapshotHash = fnv1a(snapshotValue);
      currentKeyValues.set(snapshotKey, { value:snapshotValue, hash:snapshotHash, ttlSeconds, category:'calendar_day_snapshot', calendarId });
      owned[snapshotKey] = snapshotHash;
    }

    const previousOwned = previousCalendar?.keyHashes || {};
    for (const key of Object.keys(previousOwned)) if (!(key in owned)) deleteKeys.add(key);

    nextCalendarStates[calendarId] = {
      calendarId,
      displayName:calendar.displayName,
      kind:calendar.kind,
      sourceFingerprint:fnv1a(identity),
      status:'ok',
      lastSuccessfulScanAt:cfg.scan.nowIso,
      eventCount:eventSummaries.length,
      dayOccurrenceCount:Object.keys(currentSnapshots).length,
      reminderCount:[...buckets.values()].reduce((n,a)=>n+a.length,0),
      keyHashes:owned,
      eventSnapshots:currentSnapshots,
      error:null,
    };
  } catch (error) {
    const message = error?.message || String(error);
    scanErrors.push({ calendarId, calendarName:calendar.displayName, message });
    if (previousCalendar?.keyHashes) {
      nextCalendarStates[calendarId] = {
        ...previousCalendar,
        calendarId,
        displayName:calendar.displayName,
        kind:calendar.kind,
        status:'stale_preserved',
        lastErrorAt:cfg.scan.nowIso,
        error:message,
      };
    } else {
      nextCalendarStates[calendarId] = {
        calendarId,
        displayName:calendar.displayName,
        kind:calendar.kind,
        sourceFingerprint:fnv1a(identity),
        status:'error_no_previous_state',
        lastSuccessfulScanAt:null,
        eventCount:0,
        dayOccurrenceCount:0,
        reminderCount:0,
        keyHashes:{},
        eventSnapshots:{},
        lastErrorAt:cfg.scan.nowIso,
        error:message,
      };
    }
  }
}

// Calendars removed from discovery are authoritative deletions.
for (const [calendarId, previousCalendar] of Object.entries(previousCalendars)) {
  if (!sourceCalendarIds.has(calendarId)) {
    for (const key of Object.keys(previousCalendar?.keyHashes || {})) deleteKeys.add(key);
  }
}

// Only write successful-calendar values that are new or changed.
const writes = [];
for (const [key, record] of currentKeyValues) {
  const prevHash = previousCalendars[record.calendarId]?.keyHashes?.[key];
  if (prevHash !== record.hash) writes.push({ key, value:record.value, ttlSeconds:record.ttlSeconds, category:record.category });
}
// Change-message keys are deliberately not owned by a calendar snapshot. They
// persist independently until the future sender consumes them or their TTL expires.
// Their transition-derived keys make retrying the same scan idempotent.
writes.push(...changeMessageWrites);

const stateValue = {
  schemaVersion:2,
  localDate:cfg.scan.localDate,
  timezone:targetTimezone,
  scannedAt:cfg.scan.nowIso,
  scanStartUtc:cfg.scan.startOfTodayIso,
  scanEndUtc:cfg.scan.endOfHorizonIso,
  sourceCacheGeneratedAt:sourceCache.generatedAt || null,
  reminderOffsetsMinutes:offsets,
  reminderGraceSeconds:cfg.reminderGraceSeconds,
  calendars:nextCalendarStates,
  errors:scanErrors,
  warnings:scanWarnings.slice(0,100),
};
const stateWrite = { key:cfg.scan.stateKey, value:JSON.stringify(stateValue), ttlSeconds, category:'scan_state' };
const changeMessages = changeMessageWrites.map((write) => {
  try { return JSON.parse(write.value); } catch { return null; }
}).filter(Boolean);

return [{ json: {
  status: scanErrors.length ? 'partial_error' : 'ok',
  scannedAt:cfg.scan.nowIso,
  localDate:cfg.scan.localDate,
  timezone:targetTimezone,
  calendarCount:sourceCalendarIds.size,
  successfulCalendarCount:Object.values(nextCalendarStates).filter((c)=>c.status==='ok').length,
  stalePreservedCalendarCount:Object.values(nextCalendarStates).filter((c)=>c.status==='stale_preserved').length,
  errorCalendarCount:Object.values(nextCalendarStates).filter((c)=>c.status==='error_no_previous_state').length,
  upcomingEventCount:totalEvents,
  reminderEntryCount:totalReminders,
  changedWriteCount:writes.length,
  changeMessageCount:changedMessageCount + deletedMessageCount,
  eventChangedMessageCount:changedMessageCount,
  eventDeletedMessageCount:deletedMessageCount,
  deleteCount:deleteKeys.size,
  errors:scanErrors,
  warnings:scanWarnings.slice(0,100),
  calendarRefs,
  tomorrowDate,
  changeMessages,
  redisPlan:{ deletes:[...deleteKeys], writes, stateWrite },
} }];

const plan = $('Scan Upcoming Events & Build Redis Plan').first().json.redisPlan;
const keys = Array.isArray(plan?.deletes) ? plan.deletes : [];
if (!keys.length) {
  // Deleting a guaranteed workflow-owned nonexistent key is a safe no-op and keeps
  // the sequential delete -> write chain alive.
  return [{ json:{ key:'calendar-notifier:no-op-delete:v1', noOp:true } }];
}
return keys.map((key) => ({ json:{ key, noOp:false } }));

const plan = $('Scan Upcoming Events & Build Redis Plan').first().json.redisPlan;
const writes = Array.isArray(plan?.writes) ? plan.writes : [];
if (!writes.length) {
  return [{ json:{
    key:'calendar-notifier:no-op-write:v1',
    value:JSON.stringify({ noOp:true, at:new Date().toISOString() }),
    ttlSeconds:60,
    category:'no_op',
    noOp:true,
  } }];
}
return writes.map((w) => ({ json:{ key:w.key, value:w.value, ttlSeconds:w.ttlSeconds, category:w.category, noOp:false } }));

const cfg = $('Format & Validate Config').first().json;
const scan = $('Scan Upcoming Events & Build Redis Plan').first().json;
const lookups = [];
const seen = new Set();
const add = (item) => {
  if (!item?.lookupKey) return;
  const key = `${item.lookupType}|${item.lookupKey}`;
  if (seen.has(key)) return;
  seen.add(key);
  lookups.push(item);
};

// Read the current and recent due-minute reminder buckets from Redis. Using a
// short lookback makes the sender tolerant of a delayed one-minute execution.
const nowMinuteMs = Math.floor(Number(cfg.scan.nowMs) / 60000) * 60000;
for (const cal of (scan.calendarRefs || [])) {
  for (const offset of cfg.reminderOffsetsMinutes || []) {
    for (let back = 0; back < Number(cfg.reminderLookupMinutes || 5); back++) {
      const minuteMs = nowMinuteMs - back * 60000;
      const stamp = new Date(minuteMs).toISOString().replace(/[-:]/g,'').replace(/\.000Z$/,'Z');
      add({
        lookupType:'reminder_bucket',
        lookupKey:`calendar-notifier:reminders:v1:${offset}:${stamp}:${cal.calendarId}`,
        calendarId:cal.calendarId,
        calendarName:cal.displayName,
        offsetMinutes:Number(offset),
        minuteMs,
      });
    }
  }
}

// Change/deletion messages are transition-derived. Check their sent marker
// before publishing so retries of the scan are idempotent.
for (const message of (scan.changeMessages || [])) {
  add({
    lookupType:'change_sent_marker',
    lookupKey:`calendar-notifier:sent:v1:change:${message.messageId}`,
    message,
  });
}

// At/after 21:00 local, read tomorrow's cached per-calendar snapshots and the
// per-target-day digest marker. The marker makes the digest exactly-once per day.
if (cfg.digest?.dueNow) {
  add({ lookupType:'digest_sent_marker', lookupKey:cfg.digest.markerKey, targetDate:cfg.digest.targetDate });
  for (const cal of (scan.calendarRefs || [])) {
    add({
      lookupType:'tomorrow_snapshot',
      lookupKey:`calendar-notifier:events:day:v1:${cfg.digest.targetDate}:${cal.calendarId}`,
      targetDate:cfg.digest.targetDate,
      calendarId:cal.calendarId,
      calendarName:cal.displayName,
    });
  }
}

if (!lookups.length) {
  lookups.push({ lookupType:'no_op', lookupKey:'calendar-notifier:no-op-read:v1' });
}
return lookups.map((json) => ({ json }));

const cfg = $('Format & Validate Config').first().json;
const scan = $('Scan Upcoming Events & Build Redis Plan').first().json;
const requests = $('Prepare Delivery Cache Reads').all();
const results = $input.all();
const parsed = [];
const parseMaybe = (raw) => {
  if (raw === null || raw === undefined || raw === '') return null;
  if (typeof raw === 'object') return raw;
  try { return JSON.parse(String(raw)); } catch { return null; }
};
for (let i = 0; i < requests.length; i++) {
  parsed.push({ ...requests[i].json, cacheValue:results[i]?.json?.cacheValue ?? null });
}

const reminderEntries = [];
const nonReminderCandidates = [];
const nowMs = Number(cfg.scan.nowMs);
const maxReminderAgeMs = Math.max(2, Number(cfg.reminderLookupMinutes || 5)) * 60000 + 30000;

for (const row of parsed.filter((r) => r.lookupType === 'reminder_bucket')) {
  const bucket = parseMaybe(row.cacheValue);
  if (!bucket || !Array.isArray(bucket.entries)) continue;
  for (const entry of bucket.entries) {
    const scheduledForMs = Date.parse(entry.scheduledForUtc || '');
    if (!Number.isFinite(scheduledForMs)) continue;
    if (scheduledForMs > nowMs) continue;
    if (nowMs - scheduledForMs > maxReminderAgeMs) continue;
    const scheduledMinute = String(entry.scheduledMinuteUtc || '').replace(/[-:]/g,'').replace(/\.000Z$/,'Z');
    const sentKey = `calendar-notifier:sent:v1:reminder:${entry.offsetMinutes}:${scheduledMinute}:${entry.eventKey}`;
    reminderEntries.push({
      ...entry,
      calendarId:bucket.calendarId || row.calendarId,
      calendarName:entry.calendarName || row.calendarName || '',
      sentKey,
    });
  }
}

const fmtTime = (iso) => {
  const ms = Date.parse(iso || '');
  if (!Number.isFinite(ms)) return iso || '';
  return new Intl.DateTimeFormat('en-US', {
    timeZone:cfg.timezone,
    weekday:'short', month:'short', day:'numeric', hour:'numeric', minute:'2-digit',
  }).format(new Date(ms));
};

const changedFieldLabels = {
  title:'title', start_time:'start time', end_time:'end time', location:'location',
  meeting_link:'meeting link', meeting_type:'meeting type', all_day:'all-day status',
};
for (const row of parsed.filter((r) => r.lookupType === 'change_sent_marker')) {
  if (row.cacheValue !== null && row.cacheValue !== undefined && row.cacheValue !== '') continue;
  const m = row.message || {};
  const deleted = m.messageType === 'event_deleted';
  const cancelled = deleted && m.reason === 'cancelled';
  const title = deleted
    ? `${cancelled ? 'Meeting cancelled' : 'Meeting deleted'}: ${m.title || '(untitled event)'}`
    : `Meeting changed: ${m.title || '(untitled event)'}`;
  const lines = [];
  if (m.calendarName) lines.push(`Calendar: ${m.calendarName}`);
  if (m.startUtc) lines.push(`Time: ${fmtTime(m.startUtc)}`);
  if (!deleted && Array.isArray(m.changedFields) && m.changedFields.length) {
    lines.push(`Changed: ${m.changedFields.map((f) => changedFieldLabels[f] || f).join(', ')}`);
  }
  if (m.meetingUrl) lines.push(`Join: ${m.meetingUrl}`);
  nonReminderCandidates.push({
    notificationType:m.messageType || 'event_changed',
    id:m.messageId,
    title,
    message:lines.join('\n') || title,
    click:m.meetingUrl || null,
    tags:deleted ? ['calendar','warning'] : ['calendar','arrows_counterclockwise'],
    priority:deleted ? 4 : 3,
    sentKey:row.lookupKey,
    sentTtlSeconds:Number(cfg.sentMarkerTtlSeconds),
    blockStateOnFailure:true,
  });
}

if (cfg.digest?.dueNow) {
  const digestMarker = parsed.find((r) => r.lookupType === 'digest_sent_marker');
  const digestAlreadySent = digestMarker && digestMarker.cacheValue !== null && digestMarker.cacheValue !== undefined && digestMarker.cacheValue !== '';
  if (!digestAlreadySent) {
    const events = [];
    const missingCalendars = [];
    for (const row of parsed.filter((r) => r.lookupType === 'tomorrow_snapshot')) {
      const snapshot = parseMaybe(row.cacheValue);
      if (!snapshot || !Array.isArray(snapshot.events)) {
        missingCalendars.push(row.calendarName || row.calendarId);
        continue;
      }
      for (const event of snapshot.events) events.push(event);
    }
    events.sort((a,b) => String(a.startUtc || '').localeCompare(String(b.startUtc || '')) || String(a.title || '').localeCompare(String(b.title || '')));
    const lines = [];
    if (!events.length) {
      lines.push('No meetings scheduled.');
    } else {
      for (const event of events) {
        const time = event.allDay ? 'All day' : new Intl.DateTimeFormat('en-US', {
          timeZone:cfg.timezone, hour:'numeric', minute:'2-digit'
        }).format(new Date(Date.parse(event.startUtc)));
        lines.push(`${time} — ${event.title || '(untitled event)'}${event.calendarName ? ` [${event.calendarName}]` : ''}`);
        if (event.meetingUrl) lines.push(`  ${event.meetingUrl}`);
      }
    }
    if (missingCalendars.length) {
      lines.push('', `Warning: no cached snapshot was available for: ${missingCalendars.join(', ')}`);
    }
    nonReminderCandidates.push({
      notificationType:'daily_digest',
      id:`digest:${cfg.digest.targetDate}`,
      title:`Tomorrow's meetings — ${cfg.digest.targetDate}`,
      message:lines.join('\n'),
      click:null,
      tags:['calendar'],
      priority:3,
      sentKey:cfg.digest.markerKey,
      sentTtlSeconds:Number(cfg.sentMarkerTtlSeconds),
      blockStateOnFailure:false,
    });
  }
}

// First item carries non-reminder candidates through the reminder-marker GET.
// Every reminder gets its own marker lookup item.
const out = [{ json:{
  lookupType:'delivery_meta',
  lookupKey:'calendar-notifier:no-op-read:v1',
  nonReminderCandidates,
} }];
for (const reminder of reminderEntries) {
  out.push({ json:{ lookupType:'reminder_sent_marker', lookupKey:reminder.sentKey, reminder } });
}
return out;

const cfg = $('Format & Validate Config').first().json;
const requests = $('Build Delivery Candidates & Reminder Marker Reads').all();
const results = $input.all();
const meta = requests.find((r) => r.json.lookupType === 'delivery_meta')?.json || {};
const candidates = Array.isArray(meta.nonReminderCandidates) ? [...meta.nonReminderCandidates] : [];

const fmtStart = (iso, allDay) => {
  const ms = Date.parse(iso || '');
  if (!Number.isFinite(ms)) return '';
  if (allDay) return 'All day';
  return new Intl.DateTimeFormat('en-US', {
    timeZone:cfg.timezone, weekday:'short', month:'short', day:'numeric', hour:'numeric', minute:'2-digit'
  }).format(new Date(ms));
};

for (let i = 0; i < requests.length; i++) {
  const req = requests[i]?.json || {};
  if (req.lookupType !== 'reminder_sent_marker') continue;
  const raw = results[i]?.json?.cacheValue;
  if (raw !== null && raw !== undefined && raw !== '') continue;
  const r = req.reminder || {};
  const offset = Number(r.offsetMinutes || 0);
  const when = fmtStart(r.startUtc, r.allDay);
  const title = `${r.title || '(untitled event)'} — in ${offset} minute${offset === 1 ? '' : 's'}`;
  const lines = [];
  if (when) lines.push(`Time: ${when}`);
  if (r.calendarName) lines.push(`Calendar: ${r.calendarName}`);
  if (r.meetingUrl) lines.push(`Join: ${r.meetingUrl}`);
  candidates.push({
    notificationType:'meeting_reminder',
    id:`${r.eventKey}:${offset}:${r.scheduledMinuteUtc}`,
    title,
    message:lines.join('\n') || title,
    click:r.meetingUrl || null,
    tags:['calendar','alarm_clock'],
    priority:4,
    sentKey:req.lookupKey,
    sentTtlSeconds:Number(cfg.sentMarkerTtlSeconds),
    blockStateOnFailure:false,
  });
}

if (!candidates.length) {
  return [{ json:{ noOp:true, notificationType:'none' } }];
}
return candidates.map((json) => ({ json }));

const candidates = $input.all().map((i) => i.json || {});
if (candidates.length === 1 && candidates[0].noOp) {
  return [{ json:{ noOp:true, claimKey:'calendar-notifier:claim:v1:no-op', candidate:candidates[0] } }];
}
return candidates.filter((c) => !c.noOp).map((candidate) => ({ json:{
  noOp:false,
  claimKey:String(candidate.sentKey || '').replace(/^calendar-notifier:sent:v1:/, 'calendar-notifier:claim:v1:'),
  candidate,
} }));

const requests = $('Prepare Atomic Delivery Claims').all();
const results = $input.all();
const out = [];
for (let i = 0; i < requests.length; i++) {
  const req = requests[i]?.json || {};
  if (req.noOp) {
    out.push({ json:{ noOp:true, notificationType:'none', shouldSend:false } });
    continue;
  }
  const claimKey = req.claimKey;
  const raw = results[i]?.json?.[claimKey];
  const claimCount = Number(raw);
  const candidate = req.candidate || {};
  if (claimCount === 1) {
    out.push({ json:{ ...candidate, claimKey, claimCount, shouldSend:true, claimLost:false } });
  } else {
    out.push({ json:{
      ...candidate,
      claimKey,
      claimCount:Number.isFinite(claimCount) ? claimCount : null,
      shouldSend:false,
      claimLost:true,
      success:false,
      deliveryStatus:'claimed_elsewhere',
      error:'Another workflow execution already holds the atomic Redis delivery claim',
    } });
  }
}
return out;

const cfg = $('Format & Validate Config').first().json;
const input = $input.all().map((i) => i.json || {});
if (input.length === 1 && input[0].noOp) return [{ json:{ noOp:true, success:true, notificationType:'none', deliveryStatus:'no_op' } }];

const endpoint = String(cfg.notifications.baseUrl || '').replace(/\/+$/, '');
if (!/^https?:\/\/[^\s/]+(?:\/.*)?$/i.test(endpoint)) throw new Error(`NOTIFICATIONS_BASE_URL is not a valid HTTP(S) endpoint: ${endpoint}`);
const auth = Buffer.from(`${cfg.notifications.user}:${cfg.notifications.password}`, 'utf8').toString('base64');
const out = [];
for (const candidate of input) {
  if (candidate.noOp) { out.push({ json:candidate }); continue; }
  if (!candidate.shouldSend) {
    out.push({ json:{ ...candidate, success:false, attempted:false, deliveryStatus:candidate.deliveryStatus || 'not_claimed' } });
    continue;
  }
  try {
    const headers = {
      Authorization:`Basic ${auth}`,
      'Content-Type':'application/json; charset=utf-8',
    };
    const publishBody = {
      topic:String(cfg.notifications.topic || ''),
      title:String(candidate.title || 'Calendar'),
      message:String(candidate.message || ''),
      priority:Number(candidate.priority || 3),
      tags:Array.isArray(candidate.tags) ? candidate.tags : ['calendar'],
    };
    if (candidate.click) publishBody.click = String(candidate.click);
    const res = await this.helpers.httpRequest({
      method:'POST',
      url:endpoint,
      headers,
      body:JSON.stringify(publishBody),
      encoding:'text',
      timeout:20000,
      returnFullResponse:true,
      ignoreHttpStatusErrors:true,
    });
    const statusCode = Number(res?.statusCode || 0);
    const success = statusCode >= 200 && statusCode < 300;
    out.push({ json:{ ...candidate, success, attempted:true, deliveryStatus:success ? 'sent' : 'http_error', statusCode, error:success ? null : `ntfy returned HTTP ${statusCode || 'unknown'}` } });
  } catch (error) {
    out.push({ json:{ ...candidate, success:false, attempted:true, deliveryStatus:'request_error', statusCode:null, error:error?.message || String(error) } });
  }
}
return out;

const deliveries = $('Send ntfy Notifications').all().map((i) => i.json || {});
const successes = deliveries.filter((d) => !d.noOp && d.success && d.sentKey);
if (!successes.length) {
  return [{ json:{
    key:'calendar-notifier:no-op-sent-marker:v1',
    value:JSON.stringify({ noOp:true, at:new Date().toISOString() }),
    ttlSeconds:60,
    noOp:true,
  } }];
}
return successes.map((d) => ({ json:{
  key:d.sentKey,
  value:JSON.stringify({
    schemaVersion:1,
    notificationType:d.notificationType,
    notificationId:d.id || null,
    sentAt:new Date().toISOString(),
    statusCode:d.statusCode || null,
  }),
  ttlSeconds:Number(d.sentTtlSeconds || 1209600),
  noOp:false,
} }));

const deliveries = $('Send ntfy Notifications').all().map((i) => i.json || {});
// Only release claims that this execution actually won and then failed to send.
// Never delete a claim marked claimed_elsewhere because it belongs to another execution.
const failed = deliveries.filter((d) => !d.noOp && d.shouldSend && !d.success && d.claimKey);
if (!failed.length) return [{ json:{ key:'calendar-notifier:no-op-claim-delete:v1', noOp:true } }];
return failed.map((d) => ({ json:{ key:d.claimKey, noOp:false } }));

const scan = $('Scan Upcoming Events & Build Redis Plan').first().json;
const deliveries = $('Send ntfy Notifications').all().map((i) => i.json || {}).filter((d) => !d.noOp);
// Change/deletion transitions are tied to the authoritative scan state. If this
// execution did not confirm delivery (including losing an atomic claim to an
// overlapping execution), do not advance state. The winner can advance it; if
// the winner crashes, the short claim TTL expires and a later run retries.
const blockingFailures = deliveries.filter((d) => d.blockStateOnFailure && !d.success);
if (blockingFailures.length) {
  const summary = blockingFailures.map((d) => `${d.notificationType}:${d.id || 'unknown'} (${d.error || d.deliveryStatus || 'send not confirmed'})`).join('; ');
  throw new Error(`ntfy change/deletion delivery was not confirmed; scan state was NOT advanced so the transition can retry: ${summary}`);
}
const stateWrite = scan.redisPlan?.stateWrite || null;
if (!stateWrite) {
  return [{ json:{
    key:'calendar-notifier:no-op-scan-state:v1',
    value:JSON.stringify({ noOp:true, at:new Date().toISOString() }),
    ttlSeconds:60,
    noOp:true,
  } }];
}
return [{ json:{ ...stateWrite, noOp:false } }];

const scan = $('Scan Upcoming Events & Build Redis Plan').first().json;
const deliveries = $('Send ntfy Notifications').all().map((i) => i.json || {}).filter((d) => !d.noOp);
const successful = deliveries.filter((d) => d.success);
const failed = deliveries.filter((d) => !d.success && !d.claimLost);
const claimedElsewhere = deliveries.filter((d) => d.claimLost);
const byType = {};
for (const d of successful) byType[d.notificationType] = (byType[d.notificationType] || 0) + 1;
const { redisPlan, changeMessages, calendarRefs, ...summary } = scan;
return [{ json:{
  ...summary,
  redis:{
    applied:true,
    stateApplied:Boolean(redisPlan?.stateWrite),
    stateKey:redisPlan?.stateWrite?.key || null,
  },
  delivery:{
    candidates:deliveries.length,
    sent:successful.length,
    failed:failed.length,
    claimedElsewhere:claimedElsewhere.length,
    sentByType:byType,
    failures:failed.map((d) => ({ notificationType:d.notificationType, id:d.id || null, error:d.error || null, statusCode:d.statusCode || null })),
  },
} }];
